from math import comb

# 같은 질문 5개를 4번씩 돌린 결과(True = 성공)
runs = {
    "q1": [True, True, True, True],
    "q2": [True, False, True, True],
    "q3": [True, True, True, True],
    "q4": [False, True, False, True],
    "q5": [True, True, True, False],
}

def pass_hat_k(results, k):
    n, c = len(results), sum(results)
    return comb(c, k) / comb(n, k)

for k in (1, 2, 4):
    avg = sum(pass_hat_k(r, k) for r in runs.values()) / len(runs)
    print(f"pass^{k} = {avg:.2f}")

# 에이전트 도구가 돌려줄 종목 데이터를 넘기기 전에 검사한다
from datetime import datetime, timedelta

now = datetime(2026, 11, 23, 10, 0)
rows = [
    {"symbol": "005930", "name": "삼성전자", "price": 98000, "per": 14.2, "as_of": now - timedelta(minutes=1)},
    {"symbol": "AAPL", "name": "애플", "price": None, "per": 31.0, "as_of": now - timedelta(minutes=2)},
    {"symbol": "TSLA", "name": "테슬라", "price": 351.2, "per": -5.0, "as_of": now - timedelta(days=3)},
]

def validate(r):
    errs = []
    if r["price"] is None or r["price"] <= 0:
        errs.append("가격 없음")
    if r["per"] is not None and r["per"] < 0:
        errs.append("PER 음수(적자) — '저평가'로 쓰면 안 됨")
    if now - r["as_of"] > timedelta(minutes=30):
        errs.append("30분 넘게 낡음")
    return errs

for r in rows:
    e = validate(r)
    print(r["name"], "→", "통과" if not e else ", ".join(e))

# 에이전트 한 번의 실행 기록(trajectory)을 규칙으로 검사한다
trace = [
    {"step": "router", "out": "portfolio_question"},
    {"step": "tool", "name": "get_holdings", "args": {"user": "u1"}},
    {"step": "tool", "name": "get_price", "args": {"symbol": "AAPL"}},
    {"step": "answer", "text": "보유 중인 애플 비중이 42%입니다. 지금 사세요."},
]

ALLOWED = {"portfolio_question": {"get_holdings", "get_price", "get_news"}}
BANNED = ["지금 사세요", "무조건", "확실히 오릅니다"]

def check(trace):
    problems = []
    route = trace[0]["out"]
    for s in trace:
        if s["step"] == "tool" and s["name"] not in ALLOWED[route]:
            problems.append(f"허용 안 된 도구: {s['name']}")
    tools = [s["name"] for s in trace if s["step"] == "tool"]
    if "get_holdings" not in tools:
        problems.append("보유 종목을 안 보고 답함")
    answer = trace[-1]["text"]
    for w in BANNED:
        if w in answer:
            problems.append(f"권유 표현: '{w}'")
    return problems or ["통과"]

print(check(trace))
